function updateUI(){const m=metrics(city);$('money').textContent=(city.money<0?'−':'')+'$'+Math.abs(Math.floor(city.money)).toLocaleString();$('income').textContent=(m.income>=0?'+':'−')+'$'+Math.abs(m.income).toLocaleString()+' / day';$('income').style.color=m.income>=0?'#608b6d':'#a76754';$('population').textContent=m.pop.toLocaleString();$('happiness').textContent=m.happiness+'%';$('day').textContent='Day '+city.day;$('season').textContent=['Spring','Summer','Autumn','Winter'][Math.floor((city.day-1)/30)%4]+', year '+(1+Math.floor((city.day-1)/120));$('cityName').value=city.name;$('level').textContent=tierName(m.pop);const goal=Object.keys(GRANTS).map(Number).find(v=>!city.grants.includes(v));$('goalTitle').textContent=goal?'Grow into a '+tierName(goal).toLowerCase():'Development complete';$('goalCopy').textContent=goal?`Grow to ${goal.toLocaleString()} residents. Keep homes connected, provide jobs, and look after your people.`:'All population milestones reached. Keep shaping your coast.';$('goalCount').textContent=goal?m.pop.toLocaleString()+' / '+goal.toLocaleString():m.pop.toLocaleString();$('goalProgress').style.width=(goal?Math.min(100,m.pop/goal*100):100)+'%';{const k=goal?TIERS.findIndex(([p])=>p===goal):-1,next=!city.unlockAll&&UNLOCKS[k]?UNLOCKS[k].map(unlockName):[];$('goalReward').textContent=goal?'◈ $'+GRANTS[goal].toLocaleString()+' grant'+(next.length?' · unlocks '+next.slice(0,2).join(', ')+(next.length>2?` +${next.length-2} more`:''):''):'✦ A city worth calling home';$('goalReward').title=next.length?'Unlocks: '+next.join(', '):''}checkTier();updateHud(m);if(selected)showTile(...selected);updateDashboard();renderMayor()}
