 $('operationStatus').textContent=t?.fire>0?'On fire! A fire station within 8 blocks puts it out tomorrow. Otherwise it burns down.':t?.enabled===false?'Switched off · no jobs, coverage or upkeep':'';$('operationStatus').classList.toggle('alert',t?.fire>0);
