function openReport(){document.querySelectorAll('dialog[open]').forEach(d=>d.close());updateDashboard();$('reportDialog').showModal()}
function enterWalk(){if(tourActive)finishTour(false);const road=city.grid.findIndex((t,i)=>t.type==='road'&&Math.hypot(i%N-N/2+1,Math.floor(i/N)-N/2+1)<5);if(road<0){toast('Build a road before taking a walk.');return}selectTool(null);setBuildMode('build');walkMode=true;const[x,z]=pos(road%N,Math.floor(road/N));walkPosition.set(x,2.3,z);walkYaw=.8;walkPitch=0;$('walkControls').hidden=false;$('game').classList.add('walking');toast('Welcome to street level. WASD to walk; drag to look.');heldKeys.clear()}
