const news=[];let newsIndex=0;
function nameAt(i){return(CATALOG[city.grid[i]?.type]?.name||'building').toLowerCase()}
let newsUnread=0;
function pushNews(text,i=null){news.unshift({text,i,day:city.day});news.length=Math.min(news.length,20);if($('mayorPanel').hidden){newsUnread++;$('mayorButton').classList.remove('ping');void $('mayorButton').offsetWidth;$('mayorButton').classList.add('ping')}renderMayor()}
function renderNews(){renderMayor()}
const TASKS={park:['A park nearby','Build a park, square or stadium within reach of these homes.'],education:['A school nearby','Build a school or college within reach of these homes.'],health:['Healthcare nearby','Build a clinic or hospital within reach of these homes.'],sewage:['Sewage service','Connect these homes to a sewage plant on the same streets.'],garbage:['Garbage collection','Connect these homes to a landfill, recycling center or incinerator on the same streets.'],jobs:['More jobs','Zone or build shops, workshops and offices with power and water.'],traffic:['Less traffic','The street outside is jammed. Upgrade it to a boulevard, build a highway, or add another route so cars can spread out.']};
const esc=t=>String(t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function renderMayor(){const reqs=city.requests||[],badge=reqs.length+newsUnread;$('mayorBadge').hidden=!badge;$('mayorBadge').textContent=badge>9?'9+':badge;if($('mayorPanel').hidden)return;const m=metrics(city);
 $('mayorSub').textContent=`Day ${city.day} · ${reqs.length?reqs.length+' open task'+(reqs.length>1?'s':''):'no open tasks'}`;
 $('taskList').innerHTML=reqs.length?reqs.map((r,k)=>{const span=r.kind==='jobs'?15:12,left=Math.max(0,r.due-city.day),[title,how]=TASKS[r.kind]||[r.kind,''],urgent=left<=3;const progress=r.kind==='jobs'?`<div class="task-progress"><span>${m.jobs.toLocaleString()} of ${r.target.toLocaleString()} jobs</span><i><u style="width:${Math.min(100,m.jobs/r.target*100)}%"></u></i></div>`:'';return `<article class="task-card${urgent?' urgent':''}"><div class="task-top"><b>${title}</b><span class="task-due">${left?left+' day'+(left>1?'s':'')+' left':'Due today'}</span></div><p>${r.kind==='jobs'?`Residents need work. Reach ${r.target.toLocaleString()} jobs by day ${r.due}.`:`Residents of one neighborhood are asking for ${REQUESTS[r.kind]} by day ${r.due}.`} ${how}</p>${progress||`<div class="task-time" aria-hidden="true"><i style="width:${Math.min(100,left/span*100)}%"></i></div>`}<div class="task-foot"><span class="task-reward">Reward $1,500 · +6 approval</span>${r.x>=0?`<button data-task="${k}">Show on map</button>`:''}</div></article>`}).join(''):'<p class="mayor-empty">No requests right now. Residents ask for something about every 9 days, and meeting a request pays $1,500.</p>';
 $('newsList').innerHTML=news.length?news.map((n,k)=>`<li><span class="news-day">Day ${n.day}</span><p>${esc(n.text)}</p>${n.i!=null?`<button data-news="${k}">Show on map</button>`:''}</li>`).join(''):'<li class="mayor-empty">News about your city will appear here.</li>'}
function focusTile(i){const x=i%N,y=Math.floor(i/N),[px,pz]=pos(x,y);target.set(px,0,pz);distance=Math.min(distance,210);showTile(x,y)}
function openMayor(){$('tilePanel').hidden=true;selected=null;$('mayorPanel').hidden=false;newsUnread=0;renderMayor()}
function closeMayor(){$('mayorPanel').hidden=true;renderMayor()}
function requestText(r){return r.kind==='jobs'?`Residents ask for ${REQUESTS.jobs}: reach ${r.target.toLocaleString()} jobs by day ${r.due}.`:`Residents of one neighborhood ask for ${REQUESTS[r.kind]} by day ${r.due}.`}
function handleEvents(events=[]){const ups=events.filter(e=>e.kind==='upgrade');if(ups.length)pushNews(ups.length===1?`A ${nameAt(ups[0].i)} building upgraded to level ${level(city.grid[ups[0].i])}.`:`${ups.length} buildings upgraded today, adding homes and jobs.`,ups[0].i);
 for(const e of events){const where=e.i??(e.request&&e.request.x>=0?e.request.y*N+e.request.x:null);
  if(e.kind==='fire'){pushNews(`Fire! A ${nameAt(e.i)} is burning. A fire station within 8 blocks puts it out; otherwise it burns down in three days.`,e.i);toast('Fire! See the Mayor’s office news.')}
  else if(e.kind==='extinguished')pushNews(`Firefighters put out the fire at a ${nameAt(e.i)}.`,e.i);
  else if(e.kind==='burned'){pushNews(`A ${(CATALOG[e.type]?.name||'building').toLowerCase()} burned down. A fire station nearby would protect this area.`,e.i);const[px,pz]=pos(e.i%N,Math.floor(e.i/N));visual.particles(px,3,pz,'dust',30)}
  else if(e.kind==='grant'){const k=TIERS.findIndex(([p])=>p===e.goal),names=!city.unlockAll&&UNLOCKS[k]?UNLOCKS[k].map(unlockName):[];pushNews(`Milestone reached: ${TIERS[k]?.[1]??'new tier'}, ${e.goal.toLocaleString()} residents. A $${GRANTS[e.goal].toLocaleString()} grant was added to the treasury.${names.length?' Now unlocked: '+names.join(', ')+'.':''}`);toast(`${TIERS[k]?.[1]??'Milestone'} reached! $${GRANTS[e.goal].toLocaleString()} grant${names.length?' · unlocked '+names.slice(0,4).join(', ')+(names.length>4?' and more':''):''}`);checkTier()}
  else if(e.kind==='shortage')pushNews(`${UTILITIES[e.utility].name} is running short. Blocks furthest from a plant have lost supply. Build more capacity.`);
  else if(e.kind==='request'){pushNews(requestText(e.request)+' Reward: $1,500 and +6% approval.',where);toast('New task from residents. Open the Mayor’s office to see it.')}
  else if(e.kind==='request-done'){pushNews(`Residents thank you for ${REQUESTS[e.request.kind]}. $1,500 reward and +6% approval for 10 days.`,where);toast('Request completed: $1,500 reward.')}
  else if(e.kind==='request-failed')pushNews(`Residents are disappointed: ${REQUESTS[e.request.kind]} did not arrive in time. −6% approval for 10 days.`,where)}}
$('mayorButton').onclick=()=>$('mayorPanel').hidden?openMayor():closeMayor();$('closeMayor').onclick=closeMayor;$('taskList').onclick=e=>{const b=e.target.closest('[data-task]');if(!b)return;const r=(city.requests||[])[Number(b.dataset.task)];if(r&&r.x>=0)focusTile(r.y*N+r.x)};$('newsList').onclick=e=>{const b=e.target.closest('[data-news]');if(!b)return;const n=news[Number(b.dataset.news)];if(n?.i!=null)focusTile(n.i)};
