const tourSteps=[
 {title:'Your first few blocks.',copy:'You’re the mayor. Build homes, create jobs, and keep your people connected and cared for. You already have a small town to start from.',task:'We’ll build a road, a home and a shop together. Your existing city stays yours.',focus:'.citycard'},
 {title:'Get your bearings.',copy:'<strong>Drag</strong> the map to move around. <strong>Scroll</strong> or use + and − to zoom. <strong>Right-drag</strong>, or hold <strong>Ctrl</strong> and move the mouse, to rotate. On a phone, drag and pinch to zoom.',task:'Try moving the map. The target button on the right brings you back to the center.',focus:'.map-controls'},
 {title:'Start with a road.',copy:'Buildings need a road that connects back to <strong>Town Hall</strong>. The Road tool is selected below. Click the marked block to extend the existing street.',task:'Place one connected road. It costs $60 and $1 per day to maintain.',action:'road',focus:'[data-tool="road"]'},
 {title:'Make room for residents.',copy:'The Homes tool is selected. Click the marked block next to a connected street. A home starts empty, then fills when it has <strong>power, water and enough jobs</strong>.',task:'Build one home for $320. The marked site already has road and utility access.',action:'home',focus:'[data-tool="home"]'},
 {title:'Give people a place to work.',copy:'Population growth needs jobs. A connected, powered shop with water creates <strong>32 jobs</strong>. Workshops create 55 jobs, but nearby homes dislike their pollution.',task:'Build one shop for $650 on the marked block.',action:'shop',focus:'[data-tool="shop"]'},
 {title:'Look after the neighborhood.',copy:'<strong>Power, water, sewage and garbage</strong> travel along your streets to every connected block, up to each plant’s capacity. A wind turbine makes 4 MW; a water tower holds 12K m³. <strong>Parks</strong> raise approval within 5 blocks; <strong>schools and clinics</strong> within 8.',task:'Watch the four gauges at the top. Below 100 means demand is higher than supply, and the furthest blocks lose service. Build more in the Utilities tab.',focus:'#gauges, #toolGroups'},
 {title:'Find out what a home needs.',copy:'Explore is selected. Click the marked home to open its details. <strong>✓ means supplied; ○ means missing.</strong> You can see residents, road access, power, water and nearby services.',task:'Inspect one home. Use this check whenever your population stops growing.',action:'inspect',focus:'#inspectButton'},
 {title:'Let the city come to life.',copy:'Time is running for this step. A day takes <strong>6 seconds at 1×</strong>. Each day, residents pay taxes and buildings cost upkeep. The amount beside your treasury is your <strong>net income per day</strong>.',task:'Watch the day counter and treasury. Pause with Ⅱ or Space; use 2× or 4× to speed up. If money is falling, add working shops or reduce upkeep.',focus:'.clock, .stats'},
 {title:'Let a district grow.',copy:'You can also <strong>zone</strong> empty blocks instead of buying each building. Developers build homes, shops, workshops or offices when roads, electricity and water are available. Use Shift-drag to paint several blocks.',task:'Paint one residential block for $20. The marked site is ready for development.',action:'zone',focus:'#zoneModeButton'},
 {title:'Give your city character.',copy:'The planning bar has <strong>12 architectural styles</strong>, density options and six road types. Styles affect new construction. Try the map layers to see which areas have power, water, schools or healthcare.',task:'Use the gear button for daylight, golden hour or night lighting. Try Walk streets for a ground-level view.',focus:'.city-toolbar'},
 {title:'You’re ready to be mayor.',copy:'Reach population milestones to earn <strong>grants</strong> and <strong>unlock new buildings and road types</strong>. Watch the traffic gauge: jammed streets make residents unhappy. If growth stalls, check roads, utilities and jobs. If happiness falls, add parks, schools or healthcare and move workshops away from homes.',task:'Your city autosaves on this device. Use the menu to export a backup. Replay this walkthrough anytime with the ? button or from the menu.',focus:'#menuButton'}
];
const tourPoint=new THREE.Vector3();
function setTourPause(value){paused=value;$('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Resume simulation':'Pause simulation')}
function startTour(){$('roadSelect').value='street';$('densitySelect').value='medium';$('zoneSelect').value='home';zoneType='home';if(walkMode)exitWalk();setBuildMode('build');document.querySelectorAll('dialog[open]').forEach(d=>d.close());if(!tourActive)tourPrevious={paused,speed};tourActive=true;tourIndex=0;$('game').classList.add('tour-running');$('walkthrough').hidden=false;renderTour()}
function finishTour(completed=true){tourActive=false;tourTarget=null;$('walkthrough').hidden=true;$('tourMarker').hidden=true;$('game').classList.remove('tour-running');document.querySelectorAll('.tour-glow').forEach(e=>e.classList.remove('tour-glow'));selectTool(null);if(tourPrevious){setTourPause(tourPrevious.paused);speed=tourPrevious.speed;document.querySelectorAll('[data-speed]').forEach(b=>b.classList.toggle('active',Number(b.dataset.speed)===speed))}try{localStorage.setItem('blockhaven-walkthrough-v1','seen')}catch{}if(completed)toast('You’re ready. Replay the walkthrough anytime with ?.');$('walkthroughButton').focus()}
function findTourTarget(action){const m=metrics(city),candidates=[];for(let y=3;y<N-3;y++)for(let x=3;x<N-3;x++){const t=at(city,x,y);if(!land(x,y,city.terrain))continue;if(action==='inspect'){if(t.type==='home')candidates.push([x,y]);continue}if(t.type)continue;const a=status(city,x,y,m.roads);if(!a.road)continue;if(action!=='road'&&(!a.power||!a.water))continue;candidates.push([x,y])}return candidates.sort((a,b)=>Math.hypot(a[0]-N/2,a[1]-N/2)-Math.hypot(b[0]-N/2,b[1]-N/2))[0]||null}
function renderTour(){const step=tourSteps[tourIndex];tourDone=false;tourTarget=step.action?findTourTarget(step.action):null;document.querySelectorAll('.tour-glow').forEach(e=>e.classList.remove('tour-glow'));document.querySelectorAll(step.focus).forEach(e=>e.classList.add('tour-glow'));$('tourCounter').textContent=`Getting started · ${tourIndex+1} of ${tourSteps.length}`;$('tourDots').innerHTML=tourSteps.map((_,i)=>`<i class="${i===tourIndex?'current':i<tourIndex?'complete':''}"></i>`).join('');$('tourTitle').textContent=step.title;$('tourCopy').innerHTML=step.copy;$('tourTask').textContent=step.task;$('tourTask').classList.remove('done');$('tourBack').disabled=tourIndex===0;$('tourNext').disabled=!!step.action&&!!tourTarget;$('tourNext').textContent=tourIndex===0?'Show me':tourIndex===tourSteps.length-1?'Start building':'Next';$('tourSkipStep').hidden=!step.action||!tourTarget;$('walkthrough').classList.toggle('action-step',!!step.action);$('game').classList.toggle('tour-planning',tourIndex===8||tourIndex===9);setTourPause(tourIndex!==7);$('tourTimeStatus').textContent=tourIndex===7?'Time is running. Watch your city grow.':'Time is paused while you learn.';setBuildMode('build');selectTool(step.action&&!['inspect','zone'].includes(step.action)?step.action:null);if(step.action==='zone')setBuildMode('zone');if(tourTarget){const[px,pz]=pos(...tourTarget);target.set(px,0,pz);distance=width<720?240:210;azimuth=.8;elevation=.85;if(width<720){target.x-=Math.sin(azimuth)*26;target.z-=Math.cos(azimuth)*26}}else if(tourIndex===0||tourIndex===1)center();$('tourMarkerText').textContent=step.action==='inspect'?'Inspect this home':step.action==='zone'?'Zone here':'Build here';if(step.action&&!tourTarget){$('tourTask').textContent='No suitable free site is available in this city. You can continue, or make room with the bulldozer and replay this lesson.';$('tourNext').disabled=false}document.querySelectorAll(step.focus).forEach(e=>e.classList.add('tour-glow'));$('tourTitle').focus({preventScroll:true})}
function tourAction(action,x,y){if(!tourActive||tourDone)return;const step=tourSteps[tourIndex];if(action!==step.action)return;if(action==='inspect'&&at(city,x,y)?.type!=='home')return;const m=metrics(city),a=status(city,x,y,m.roads);if(action==='road'&&!m.roads.has(y*N+x))return;if(['home','shop','zone'].includes(action)&&(!a.road||!a.power||!a.water)){toast('Use a site with connected roads, power and water. The marked block is ready.');return}if(action==='zone'&&!at(city,x,y)?.zone)return;tourDone=true;tourTarget=null;$('tourMarker').hidden=true;$('tourTask').classList.add('done');$('tourTask').textContent=action==='road'?'✓ Road connected. Your new block is part of the town’s street network.':action==='home'?'✓ Home built with roads, power and water. Residents can move in when time runs.':action==='shop'?'✓ Shop built. That’s 32 more jobs for your growing neighborhood.':action==='zone'?'✓ Residential district painted. Let time run and developers will build it.':'✓ Home inspected. Missing services show an open circle; supplied services show a check.';$('tourNext').disabled=false;$('tourSkipStep').hidden=true}
function positionTourMarker(){if(!tourActive||!tourTarget){$('tourMarker').hidden=true;return}const[px,pz]=pos(...tourTarget);tourPoint.set(px,1,pz).project(camera);$('tourMarker').hidden=tourPoint.z>1||Math.abs(tourPoint.x)>1||Math.abs(tourPoint.y)>1;$('tourMarker').style.left=((tourPoint.x+1)*width/2)+'px';$('tourMarker').style.top=((1-tourPoint.y)*height/2)+'px';tileHighlight.visible=true;tileHighlight.position.set(px,.6,pz);tileHighlight.material.color.set('#f4cb72')}
$('tourNext').onclick=()=>{if(tourIndex===tourSteps.length-1)finishTour();else{tourIndex++;renderTour()}};$('tourBack').onclick=()=>{if(tourIndex>0){tourIndex--;renderTour()}};$('tourSkipStep').onclick=()=>{tourIndex++;renderTour()};$('tourExit').onclick=()=>finishTour(false);$('walkthroughButton').onclick=startTour;$('replayTourButton').onclick=startTour;
