const popOf=c=>c.grid.reduce((a,t)=>a+(t.type==='home'?t.pop||0:0),0);
function cityNote(c){return `${c.name} · Day ${c.day} · ${popOf(c).toLocaleString()} residents · ${c.size??32} × ${c.size??32}`}
function titlePanel(name){for(const id of ['titleHome','titleNewPanel','titleLoadPanel'])$(id).hidden=id!==name;const first=$(name).querySelector('button:not([hidden]),input');first?.focus({preventScroll:true})}
function showTitle(){if(tourActive)finishTour(false);if(walkMode)exitWalk();document.querySelectorAll('dialog[open]').forEach(d=>d.close());selectTool(null);$('tilePanel').hidden=true;$('mayorPanel').hidden=true;if(hadSave||city.day>1)save();atTitle=true;$('game').classList.add('at-title');$('titleScreen').hidden=false;$('titleContinue').hidden=!(hadSave||city.day>1);$('titleContinueNote').textContent=cityNote(city);const n=readSlots().length;$('titleLoadNote').textContent=n?`${n} saved ${n===1?'city':'cities'} and city files`:'City files and backups';$('titleKeepNote').hidden=$('titleContinue').hidden;titlePanel('titleHome')}
function leaveTitle(){atTitle=false;hadSave=true;$('game').classList.remove('at-title');$('titleScreen').hidden=true;center();updateUI();layoutHud();canvas.focus({preventScroll:true});if(!tourSeen){tourSeen=true;startTour()}else toast('Welcome back to '+city.name+'.')}
function keepCurrent(){if(!(hadSave||city.day>1))return;try{const slots=readSlots();slots.push({savedAt:Date.now(),city:packCity(city)});localStorage.setItem('blockhaven-slots',JSON.stringify(slots.slice(-8)))}catch{}}
function openCity(next){keepCurrent();city=adopt(next);undoStack.length=0;elapsed=0;shownTier=-1;rebuild();save();leaveTitle()}
function renderTitleSlots(){const slots=readSlots();$('titleSlots').replaceChildren();if(!slots.length){const p=document.createElement('p');p.className='title-note';p.textContent='No saved cities yet. Snapshots you save from the city menu, and cities you replace, appear here.';$('titleSlots').append(p);return}slots.map((slot,index)=>({slot,index})).reverse().forEach(({slot,index})=>{try{const saved=validateCity(slot.city);setMapSize(city.size??32);const b=document.createElement('button');b.className='title-btn small-btn';b.innerHTML='<span><b></b><small></small></span><i>▶</i>';b.querySelector('b').textContent=saved.name;b.querySelector('small').textContent=`Day ${saved.day} · ${popOf(saved).toLocaleString()} residents · ${saved.size??32} × ${saved.size??32} · saved ${new Date(slot.savedAt).toLocaleDateString()}`;b.onclick=()=>{const rest=readSlots().filter((_,k)=>k!==index);try{localStorage.setItem('blockhaven-slots',JSON.stringify(rest))}catch{}openCity(validateCity(slot.city))};$('titleSlots').append(b)}catch{setMapSize(city.size??32)}})}
$('titleContinue').onclick=leaveTitle;
$('titleNew').onclick=()=>{$('titleCityName').value=hadSave||city.day>1?'':'New Port';$('titleCityName').placeholder='New Port';titlePanel('titleNewPanel')};
$('titleLoad').onclick=()=>{renderTitleSlots();titlePanel('titleLoadPanel')};
$('titleHelp').onclick=()=>$('helpDialog').showModal();$('titleSettings').onclick=openGraphics;
document.querySelectorAll('[data-title-back]').forEach(b=>b.onclick=()=>titlePanel('titleHome'));
document.querySelectorAll('.terrain-card').forEach(b=>b.onclick=()=>{titleTerrain=b.dataset.terrain;document.querySelectorAll('.terrain-card').forEach(c=>{c.classList.toggle('active',c===b);c.setAttribute('aria-checked',String(c===b))})});
$('titleFound').onclick=()=>{const size=Number($('titleMapSize').value);keepCurrent();const next=newCity(titleTerrain,size);next.name=$('titleCityName').value.trim()||'New Port';if($('titleSandbox').checked)next.unlockAll=true;city=adopt(next);undoStack.length=0;elapsed=0;shownTier=-1;rebuild();save();leaveTitle()};
$('titleImportFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>3e7)throw Error('too large');const next=validateCity(JSON.parse(await f.text()));openCity(next)}catch{setMapSize(city.size??32);toast('That file is not a valid Blockhaven city. Choose an exported .json file.')}e.target.value=''};
$('titlePaste').onclick=()=>{$('backupText').value='';$('pasteDialog').showModal()};
$('mainMenuButton').onclick=showTitle;document.querySelector('.brand').onclick=e=>{e.preventDefault();showTitle()};
showTitle();

function animate(ms){if(graphicsLost)return;requestAnimationFrame(animate);const dt=Math.min((ms-last)/1000,.1);last=ms;const modal=!!document.querySelector('dialog[open]'),running=!atTitle&&!paused&&!modal&&(!tourActive||tourIndex===7);if(atTitle&&!settings.reducedMotion)azimuth+=dt*.035;if(running){elapsed+=dt*speed;while(elapsed>=6){elapsed-=6;const changes=tick(city);changes.forEach(i=>{const t=city.grid[i];createBlock(i%N,Math.floor(i/N),!!t.type&&!t.fire&&!changes.events.some(e=>e.i===i&&e.kind!=='upgrade'))});if(changes.length){makeCars();updateLayer()}handleEvents(changes.events);if(changes.grant)visual.particles(target.x,18,target.z,'celebrate',70);refreshBadges();changed();updateUI()}}
 visual.update(dt,speed,running,elapsed/6);if(walkMode){updateWalking(dt,modal);camera.position.copy(walkPosition);camera.lookAt(walkPosition.x+Math.sin(walkYaw)*10,walkPosition.y+Math.sin(walkPitch)*10,walkPosition.z+Math.cos(walkYaw)*10)}else{camera.position.set(target.x+distance*Math.cos(elevation)*Math.sin(azimuth),distance*Math.sin(elevation),target.z+distance*Math.cos(elevation)*Math.cos(azimuth));camera.lookAt(target)}camera.updateMatrixWorld();positionTourMarker();visual.render();if(!$('bootStatus').hidden)$('bootStatus').hidden=true;if(frame++%30===0){const r=visual.stats();$('renderStats').textContent=`${r.fps} fps · ${r.drawCalls.toLocaleString()} draws · ${Math.round(r.triangles/1000)}k triangles`;$('sceneTime').textContent=settings.lighting==='night'?'After dark':settings.lighting==='sunset'?'Golden hour':settings.lighting==='cycle'?'Day / night cycle':'Daylight'}}visual.update(.001,speed,false);renderer.compileAsync(scene,camera).then(()=>requestAnimationFrame(animate)).catch(e=>{$('bootMessage').textContent='The 3D scene did not finish loading. Try low graphics or reload the page.';console.error(e)});canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();graphicsLost=true;$('bootStatus').hidden=false;$('bootMessage').textContent='The graphics connection was interrupted. Reload the page or try low graphics; your saved city stays on this device.'});

// Screenshot hook: open with ?camera to aim the view from scripts.
if(new URLSearchParams(location.search).has('camera'))window.aimCamera=(x,y,d,el,az)=>{const[px,pz]=pos(x,y);target.set(px,0,pz);distance=d;elevation=el;azimuth=az};
